  'admin/domain/help_tip' => 'Подсказка:<br>
                        1. Функция позволяет для разных доменов одной базы данных в нестатическом режиме показывать разные шаблоны и настройки сайта.<br>
                        2. Число сайтов по доменам не ограничено.<br>
                        3. Формат импортируемого текста: домен$название сайта$ключевые слова$описание$шаблон$каталог шаблона$каталог рекламы$карта$мобильный шаблон$домен мобильной версии. По одному сайту в строке. Существующие данные очищаются.<br>
                        4. Если задан каталог карты, редирект nginx администратор настраивает сам; URL: rss/$каталог_карты/index.xml.<br>
                        5. Пустой мобильный шаблон отключает мобильный шаблон этого сайта. Домен мобильной версии работает только в режиме «Адаптив для мобильных = Несколько доменов»: при входе с телефона по этому домену используется мобильный шаблон этого сайта.<br>',
