  'admin/index/quickmenu/tip' => 'Требования к формату: 1. Название меню, адрес ссылки; 2. Каждое быстрое меню — на отдельной строке; <br>     1. Поддерживаются внешние адреса, например: Журнал обновлений,//www.baidu.com/ <br>     2. Поддерживаются файлы плагинов, например: Меню файла плагина,/index.php/addons/plugin/controller/action <br>     3. Поддерживаются модули системы, например: Управление статьями,art/data <br>     4. Поддерживаются разделители, например: Разделитель,###',
