  'admin/index/welcome/seven_day_visit_data' => 'Просмотры за 7 дней',
  'admin/index/welcome/system_info_guide' => '
        <div class="text-sm">
            <p class="font-bold">Как читать системный статус на дашборде</p>
            <p class="mt-2">Если «Системная информация» (CPU, память, диск) на дашборде показывает 0, причина обычно в конфигурации PHP-окружения. Настройте <code>php.ini</code> с учётом политики безопасности вашего сервера, используя описанные ниже способы.</p>
            <br>
            <p class="font-bold mt-4">Способ 1: стандартные настройки (проще всего)</p>
            <p>При этом способе вся информация отображается корректно. Убедитесь, что перечисленные функции <strong>не</strong> отключены в параметре <code>disable_functions</code>:</p>
            <ul class="list-disc list-inside pl-4">
                <li><code>shell_exec</code></li>
                <li><code>disk_total_space</code></li>
                <li><code>disk_free_space</code></li>
            </ul>
            <br>
            <p class="font-bold mt-4">Способ 2: повышенная безопасность</p>
            <p>Если по соображениям безопасности <code>shell_exec</code> обязательно нужно отключить и при этом включён <code>open_basedir</code>, выполните следующие настройки, чтобы выводить данные CPU и памяти:</p>
            <ol class="list-decimal list-inside pl-4">
                <li><strong>Отключите <code>shell_exec</code></strong>: добавьте <code>shell_exec</code> в <code>disable_functions</code>.</li>
                <li><strong>Разрешите каталог <code>/proc</code></strong>: добавьте <code>/proc/</code> в путь <code>open_basedir</code>. Тогда программа сможет читать файлы информации ядра как запасной вариант, когда выполнение команд недоступно.</li>
            </ol>
            <p class="mt-2"><strong>Пример</strong> (замените <code>/var/www/html/maccms</code> на реальный путь к вашему сайту):</p>
            <pre class="bg-gray-100 p-2 rounded text-xs"><code>open_basedir = /var/www/html/maccms/:/tmp/:/proc/</code></pre>
            <div class="mt-4 p-2 bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700">
                <p><strong class="font-bold">Важно</strong>: после изменения <code>php.ini</code> нужно <strong>перезапустить службу PHP-FPM</strong> (или Apache), чтобы настройки вступили в силу.</p>
            </div>
        </div>
    ',
